records.sql:
SELECT AVG(unemployment_1996) AS avg_unemployment_1996
FROM districts
WHERE region = 'east Bohemia';

SELECT COUNT(*) AS women_count
FROM clients
WHERE gender = 'female';

SELECT MAX(
    FLOOR(DATEDIFF('1999-01-01', birth_date) / 365.25)
) AS oldest_age
FROM clients;

SELECT COUNT(*) AS client_count
FROM clients
WHERE birth_date BETWEEN '1970-01-01' AND '1979-12-31';

SELECT DISTINCT term_months
FROM loans
ORDER BY term_months ASC;

SELECT ROUND(
         100.0 * SUM(CASE WHEN status = 'D' THEN 1 ELSE 0 END) / COUNT(*),
         1
       ) AS pct_running_in_debt
FROM loan;

SELECT MAX(approval_date) AS most_recent_approval_date
FROM loans
WHERE status = 'finished_not_paid';

SELECT COUNT(*) AS loan_count
FROM loans
WHERE term = 60;

SELECT COUNT(*) AS gold_card_count
FROM credit_cards
WHERE card_type = 'gold';

SELECT ROUND(
    100.0 * SUM(CASE WHEN card_type = 'classic' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS classic_percentage
FROM credit_card;

SELECT MIN(issue_date) AS earliest_issue_date
FROM cards
WHERE card_type = 'gold';

SELECT MAX(issue_date) AS most_recent_issue_date
FROM cards
WHERE card_type = 'junior';

SELECT COUNT(*) AS total_cards_issued
FROM CreditCards
WHERE YEAR(issue_date) = 1998;

SELECT COUNT(*) / 12.0 AS avg_cards_per_month
FROM credit_cards
WHERE EXTRACT(YEAR FROM issue_date) = 1997;

SELECT COUNT(*) AS credit_card_count
FROM credit_cards
WHERE issue_date < '1996-01-01';

SELECT ROUND(
    100.0 * SUM(CASE WHEN card_type = 'gold' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS gold_card_percentage
FROM credit_cards
WHERE YEAR(issue_date) = 1998;

SELECT COUNT(*) AS credit_transaction_count
FROM transactions
WHERE type = 'credit';

SELECT SUM(amount) AS total_credit_amount
FROM transactions
WHERE type = 'credit';

SELECT ROUND(
    100.0 * SUM(CASE WHEN transaction_type = 'cash_deposit' THEN 1 ELSE 0 END)
    / COUNT(*),
    2
) AS cash_deposit_percentage
FROM transactions;

SELECT COUNT(*) AS transaction_count
FROM transactions
WHERE YEAR(transaction_date) = 1997;

SELECT COUNT(*) AS negative_balance_count
FROM transactions
WHERE balance < 0;

SELECT ROUND(AVG(balance), 2) AS average_resulting_balance
FROM transactions
WHERE type = 'sanction interest';

SELECT SUM(amount) AS total_dollars
FROM transactions
WHERE transaction_type = 'old-age pension';

SELECT COUNT(*) AS insurance_standing_order_count
FROM standing_orders
WHERE purpose = 'insurance';

SELECT AVG(amount) AS average_amount
FROM standing_orders
WHERE purpose = 'Leasing';

SELECT MAX(Amount) AS MaxStandingOrderAmount
FROM StandingOrders
WHERE Purpose = 'Loan Repayment';

SELECT MIN(amount) AS minimum_amount
FROM standing_orders
WHERE payment_type = 'insurance';

SELECT COUNT(*) AS standing_order_count
FROM standing_orders
WHERE amount > 10000;

SELECT COUNT(*) AS standing_order_count
FROM standing_orders
WHERE amount BETWEEN 1000 AND 5000;

SELECT COUNT(*) AS district_count
FROM districts
WHERE region = 'South Moravia';

SELECT SUM(population) AS total_population
FROM districts
WHERE region = 'Central Bohemia';

SELECT SUM(amount_usd) AS total_old_age_pension_usd
FROM pension_payments
WHERE payment_type = 'old_age';

SELECT COUNT(DISTINCT account_id) AS account_count
FROM statements
WHERE statement_frequency = 'weekly';

SELECT AVG(approved_amount_usd) AS average_approved_amount
FROM loans
WHERE status = 'finished_no_problems';

SELECT ROUND(
    100.0 * SUM(CASE WHEN statement = 'monthly' THEN 1 ELSE 0 END) / COUNT(*),
    1
) AS pct_monthly_statements
FROM accounts;

SELECT MIN(opening_date) AS earliest_opening_date
FROM accounts
WHERE statement_frequency = 'weekly';

SELECT COUNT(*) AS account_count
FROM accounts
WHERE region = 'Prague';

SELECT COUNT(*) AS client_count
FROM clients
WHERE region = 'Prague';

SELECT ROUND(
         100.0 * SUM(CASE WHEN region = 'South Moravia' THEN 1 ELSE 0 END) / COUNT(*),
         2
       ) AS south_moravia_percentage
FROM clients;

SELECT COUNT(*) AS total_clients
FROM clients
WHERE region IN ('Central Bohemia', 'East Bohemia', 'North Bohemia');

SELECT ROUND(AVG(cnt), 2) AS avg_accounts_per_disponent
FROM (
    SELECT client_id, COUNT(DISTINCT account_id) AS cnt
    FROM disponent
    GROUP BY client_id
) t;

SELECT MAX(account_count) AS max_accounts
FROM (
    SELECT client_id, COUNT(*) AS account_count
    FROM accounts
    GROUP BY client_id
) AS counts;

SELECT ROUND(
         100.0 * SUM(CASE WHEN d.region = 'Prague' THEN 1 ELSE 0 END) / COUNT(*),
         2
       ) AS prague_pct
FROM account a
JOIN district d ON a.district_id = d.district_id;

SELECT 100.0 * SUM(CASE WHEN sex = 'F' THEN 1 ELSE 0 END) / COUNT(*) AS pct_women
FROM client
WHERE region = 'south Moravia';
